const state={logged:false,live:false,capture:null,outputCapture:null,sceneTimer:0,recorder:null,ws:null,wsUrl:'',reconnects:0,relaySession:'',destination:'YouTube',ingests:(()=>{const saved=JSON.parse(localStorage.getItem('lumacast-ingests')||'[]'),secrets=JSON.parse(sessionStorage.getItem('lumacast-ingest-keys')||'{}');return saved.map(x=>({...x,key:secrets[x.title]||''}))})(),activeIngest:sessionStorage.getItem('lumacast-active-ingest')||'YouTube',youtubeToken:'',youtubeChannel:'',orientation:'Auto',imageScale:100,imageBox:{width:100,height:24,visible:true,locked:false,mode:'Fit',centered:false,rotation:0},imageOnTop:true,positions:{image:{x:0,y:0},overlay:{x:0,y:0}},video:{width:100,height:100,x:0,y:0},audio:{game:{gain:40,pan:0},mic:{gain:100,pan:0}},audioNodes:{},audioContext:null,micStream:null,micDevices:[],micDeviceId:'',micDeviceLabel:'Device Microphone',selectedHeadset:'',micManualSelection:false,speakerEnabled:true,page:'dashboard',modal:'',resolution:'720p',fps:60,bitrate:9000,mode:'Advanced',tab:'Video',visible:true,aspect:false,bgColor:'#8170c4',image:null,widgets:[],settings:{'Adaptive Bitrate':false,'Constant Bitrate':true,'Speed over quality':true,'Lock on low resolution':false},priority:'High',values:{Gamma:0,Contrast:0,Brightness:0,Saturation:0,'Hue Shift':0,Opacity:1}};
