function sceneRatio(){return state.orientation==='Portrait'?'9 / 16':'16 / 9'}
function colorFilterCss(){const v=state.values||{},gamma=Math.pow(2,(Number(v.Gamma)||0)*.22),brightness=Math.max(0,1+(Number(v.Brightness)||0)*.5)*gamma,contrast=Math.max(0,1+(Number(v.Contrast)||0)*.5),saturation=Math.max(0,1+(Number(v.Saturation)||0)),hue=Number(v['Hue Shift'])||0;return `brightness(${brightness}) contrast(${contrast}) saturate(${saturation}) hue-rotate(${hue}deg)`}
