function imageLayer(){if(!state.image)return '';const p=state.positions.image,b=state.imageBox||{width:100,height:24,visible:true,locked:false,mode:'Fit',centered:false,rotation:0};const editing=state.modal==='editor'&&state.tab==='Image';return `<div onclick="event.stopPropagation();state.tab='Image';openModal('editor')" onpointerdown="if(state.modal==='editor'&&state.tab==='Image')startImageDrag(event,'move')" class="scene-image-layer ${editing?'selected':''} ${b.visible?'':'layer-hidden'}" style="width:${b.width}%;height:${b.height}%;left:calc(50% + ${p.x}%);top:calc(50% + ${p.y}%);z-index:${state.imageOnTop?2:0};background-image:${b.mode==='Pattern'?`url(${state.image})`:'none'};transform:translate(-50%,-50%) rotate(${b.rotation}deg)"><img class="scene-image ${b.mode==='Pattern'?'pattern-source':''} ${state.outputCapture&&!state.modal?'canvas-source':''}" src="${state.image}" style="object-fit:${b.mode==='Fit'?'contain':'cover'};width:100%;height:100%">${editing&&!b.locked?'<i class="image-handle handle-left" onpointerdown="startImageDrag(event,\'left\')"></i><i class="image-handle handle-right" onpointerdown="startImageDrag(event,\'right\')"></i><i class="image-handle handle-top" onpointerdown="startImageDrag(event,\'top\')"></i><i class="image-handle handle-bottom" onpointerdown="startImageDrag(event,\'bottom\')"></i>':''}</div>`}
function startImageDrag(event,mode){if(event.target.closest('button'))return;const b=state.imageBox;if(!b||b.locked)return;event.preventDefault();event.stopPropagation();const rect=event.currentTarget.closest('.editor-preview').getBoundingClientRect(),start={x:event.clientX,y:event.clientY,left:state.positions.image.x,top:state.positions.image.y,width:b.width,height:b.height};const move=e=>{const dx=e.clientX-start.x,dy=e.clientY-start.y;if(mode==='move'){if(Math.abs(dx)+Math.abs(dy)>1){b.centered=false;const toggle=document.querySelector('#imageCentered');if(toggle)toggle.checked=false}state.positions.image.x=start.left+dx/rect.width*100;state.positions.image.y=start.top+dy/rect.height*100}else if(mode==='left'||mode==='right'){b.width=Math.max(5,Math.min(100,start.width+(mode==='right'?1:-1)*dx/rect.width*100));if(b.centered)state.positions.image.x=start.left+(mode==='right'?dx/rect.width*50:-dx/rect.width*50)}else if(mode==='top'||mode==='bottom'){b.height=Math.max(5,Math.min(100,start.height+(mode==='bottom'?1:-1)*dy/rect.height*100));if(b.centered)state.positions.image.y=start.top+(mode==='bottom'?dy/rect.height*50:-dy/rect.height*50)}const layer=document.querySelector('.scene-image-layer');if(layer){layer.style.width=b.width+'%';layer.style.height=b.height+'%';layer.style.left=`calc(50% + ${state.positions.image.x}%)`;layer.style.top=`calc(50% + ${state.positions.image.y}%)`}};const end=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);if(state.modal==='editor')renderModal()};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end,{once:true})}
function videoLayer(){const p=state.video;return `<div onclick="event.stopPropagation();state.tab='Video';openModal('editor')" class="editor-video-layer ${state.visible?'':'layer-hidden'} ${state.modal==='editor'&&state.tab==='Video'?'selected':''}" style="width:${p.width}%;height:${p.height}%;left:calc(50% + ${p.x}%);top:calc(50% + ${p.y}%)">${state.capture?`<video id="editorVideoPreview" style="object-fit:${state.aspect?'contain':'fill'};filter:${colorFilterCss()};opacity:${state.values.Opacity}" autoplay muted playsinline oncanplay="this.play()"></video>`:`<span>Video (${state.orientation})</span>`}</div>`}
function nudgePad(target){const step=target==='video'?1:8,unit=target==='video'?'%':'px';return `<div class="nudge-control"><button onclick="nudge('${target}',0,-${step})">Up</button><div><button onclick="nudge('${target}',-${step},0)">Left</button><button onclick="nudge('${target}',0,${step})">Bottom</button><button onclick="nudge('${target}',${step},0)">Right</button></div><small>Fine position · ${step}${unit}</small></div>`}
function positionSliders(target,label){const audioTarget=target==='game'||target==='mic',imageTarget=target==='image',videoTarget=target==='video',p=videoTarget?state.video:audioTarget?{x:state.audio[target].pan,y:state.audio[target].gain}:state.positions[target]||state.positions.overlay,min=imageTarget?'-50':audioTarget?'-100':videoTarget?'-50':'-480',max=imageTarget?'50':audioTarget?'100':videoTarget?'50':'480',ymin=videoTarget?'-50':min,ymax=videoTarget?'50':max,unit=imageTarget||videoTarget||audioTarget?'%':'px',xLabel=imageTarget?'Position X':audioTarget?'Left / right balance':videoTarget?'Position X':label+' horizontal',yLabel=imageTarget||videoTarget?'Position Y':label+' vertical';return `<div class="position-scroll ${imageTarget?'image-position':''} ${videoTarget?'video-position':''}"><label>${xLabel} <b>${p.x}${unit}</b><input type="range" min="${min}" max="${max}" step="${imageTarget||videoTarget?'0.1':'1'}" value="${p.x}" oninput="setPosition('${target}','x',this.value,this)"></label>${audioTarget?'':`<label>${yLabel} <b>${p.y}${unit}</b><input type="range" min="${ymin}" max="${ymax}" step="${imageTarget||videoTarget?'0.1':'1'}" value="${p.y}" oninput="setPosition('${target}','y',this.value,this)"></label>`}</div>`}
function clampVideo(){const p=state.video;p.x=Math.max(-(100-p.width)/2,Math.min((100-p.width)/2,p.x));p.y=Math.max(-(100-p.height)/2,Math.min((100-p.height)/2,p.y))}
