function nudge(target,dx,dy){if(target==='game'||target==='mic'){const a=state.audio[target];if(dx)a.pan=Math.max(-100,Math.min(100,a.pan+dx/8*5));if(dy)a.gain=Math.max(0,Math.min(100,a.gain-dy/8*5));updateAudioNodes();renderModal();return}if(target==='video'){state.video.x=Math.max(-50,Math.min(50,state.video.x+dx));state.video.y=Math.max(-50,Math.min(50,state.video.y+dy));renderModal();return}const p=state.positions[target]||state.positions.overlay;p.x+=dx;p.y+=dy;renderModal()}
function imageControls(){const b=state.imageBox;return `<div class="settings-card image-edit-controls"><div class="setting-row"><span>Visible</span><input class="switch" type="checkbox" ${b.visible?'checked':''} onchange="bumpImage('visible',this.checked)"></div><div class="setting-row"><span>Locked</span><input class="switch" type="checkbox" ${b.locked?'checked':''} onchange="bumpImage('locked',this.checked)"></div><div class="row-card"><span>Image</span><button class="link-button" onclick="document.querySelector('#photoInput').click()">Update</button></div><div class="segmented image-mode">${['Fit','Fill','Pattern'].map(x=>`<button class="${b.mode===x?'selected':''}" onclick="bumpImage('mode','${x}')">${x}</button>`).join('')}</div><div class="setting-row"><span>Centered</span><input id="imageCentered" class="switch" type="checkbox" ${b.centered?'checked':''} onchange="bumpImage('centered',this.checked)"></div>${positionSliders('image','Position')}<div class="setting-row"><span>Reorder</span><button class="link-button image-icon" aria-label="Change image layer order" onclick="state.imageOnTop=!state.imageOnTop;renderModal()">▢</button></div><div class="setting-row"><span>Rotate</span><button class="link-button image-icon" aria-label="Rotate image" onclick="state.imageBox.rotation=(state.imageBox.rotation+90)%360;renderModal()">↻</button></div><button class="remove" onclick="state.image=null;state.tab='Add';renderModal()">Remove</button></div>`}
function bumpImage(key,value){state.imageBox[key]=value;if(key==='centered'&&value){state.positions.image.x=0;state.positions.image.y=0}renderModal()}
function audioChannel(name,label){const a=state.audio[name];return `<div class="settings-group"><h3>${label}</h3><div class="settings-card"><div class="slider-line"><div><b>Level</b><small>Gain · ${a.gain}%</small></div><input class="range" type="range" min="0" max="100" value="${a.gain}" oninput="state.audio.${name}.gain=+this.value;updateAudioNodes();this.previousElementSibling.querySelector('small').textContent='Gain · '+this.value+'%'"><span class="slider-value">${a.gain}%</span></div>${positionSliders(name,label)}<small class="helper">Position sliders adjust ${name==='game'?'stereo pan and output balance':'mic mix pan and level'} smoothly.</small></div></div>`}
function updateAudioNodes(){for(const name of ['game','mic']){const n=state.audioNodes[name];if(n){n.gain.gain.value=name==='game'&&!state.speakerEnabled?0:state.audio[name].gain/100;if(n.pan)n.pan.pan.value=state.audio[name].pan/100}}}
async function refreshMicDevices(){try{const all=await navigator.mediaDevices.enumerateDevices(),devices=all.filter(d=>d.kind==='audioinput'),outputs=all.filter(d=>d.kind==='audiooutput');state.micDevices=devices;const preferred=devices.find(d=>/headset|headphone|airpod|bluetooth|wireless/i.test(d.label));const chosen=(state.micManualSelection&&devices.find(d=>d.deviceId===state.micDeviceId))||preferred||(state.micDeviceId&&devices.find(d=>d.deviceId===state.micDeviceId))||devices.find(d=>d.deviceId==='default')||devices[0];if(chosen){state.micDeviceId=chosen.deviceId;state.micDeviceLabel=chosen.label|| (preferred?'Headset Microphone':'Device Microphone');state.selectedHeadset=outputs.find(d=>/headset|headphone|airpod|bluetooth|wireless/i.test(d.label))?.label||preferred?.label||''}}catch{state.micDevices=[]}}
async function enableMic(){try{const manuallyChosen=state.micManualSelection,choice=document.querySelector('#micSource')?.value;if(manuallyChosen&&choice)state.micDeviceId=choice;let stream=await navigator.mediaDevices.getUserMedia({audio:state.micDeviceId?{deviceId:{exact:state.micDeviceId}}:true});await refreshMicDevices();const preferred=state.micDevices.find(d=>/headset|headphone|airpod|bluetooth|wireless/i.test(d.label));if(!manuallyChosen&&preferred&&preferred.deviceId!==state.micDeviceId){state.micDeviceId=preferred.deviceId;stream.getTracks().forEach(t=>t.stop());stream=await navigator.mediaDevices.getUserMedia({audio:{deviceId:{exact:preferred.deviceId}}})}state.micStream?.getTracks().forEach(t=>t.stop());state.micStream=stream;const track=stream.getAudioTracks()[0];state.micDeviceLabel=track?.label||state.micDeviceLabel;toast(`Using ${state.micDeviceLabel}.`);if(state.modal==='audio')renderModal()}catch(e){toast('Microphone permission was not granted or that microphone is unavailable.')}}
function drawImageLayer(ctx,canvas){const b=state.imageBox,img=document.querySelector('.scene-image');if(!state.image||!b.visible||!img?.complete||!img.naturalWidth)return;const w=canvas.width*b.width/100,h=canvas.height*b.height/100,p=state.positions.image,cx=canvas.width/2+p.x*canvas.width/100,cy=canvas.height/2+p.y*canvas.height/100;ctx.save();ctx.translate(cx,cy);ctx.rotate(b.rotation*Math.PI/180);ctx.beginPath();ctx.rect(-w/2,-h/2,w,h);ctx.clip();if(b.mode==='Pattern'){const pat=ctx.createPattern(img,'repeat');if(pat){ctx.fillStyle=pat;ctx.fillRect(-w/2,-h/2,w,h)}}else{const scale=b.mode==='Fit'?Math.min(w/img.naturalWidth,h/img.naturalHeight):Math.max(w/img.naturalWidth,h/img.naturalHeight),dw=img.naturalWidth*scale,dh=img.naturalHeight*scale;ctx.drawImage(img,-dw/2,-dh/2,dw,dh)}ctx.restore()}
async function makeSceneCapture(source){const canvas=document.createElement('canvas'),portrait=state.orientation==='Portrait';canvas.width=portrait?1080:1920;canvas.height=portrait?1920:1080;const ctx=canvas.getContext('2d',{alpha:false});const video=document.createElement('video');video.muted=true;video.playsInline=true;video.srcObject=source;await video.play();state.previewVideo=video;const output=canvas.captureStream(state.fps);const AudioCtx=window.AudioContext||window.webkitAudioContext;if(AudioCtx){state.audioContext=new AudioCtx();const dest=state.audioContext.createMediaStreamDestination();const streams=[['game',source],['mic',state.micStream]].filter(([,s])=>s);for(const [name,stream] of streams){for(const track of stream.getAudioTracks()){const src=state.audioContext.createMediaStreamSource(new MediaStream([track])),gain=state.audioContext.createGain(),pan=state.audioContext.createStereoPanner?.();gain.gain.value=name==='game'&&!state.speakerEnabled?0:state.audio[name].gain/100;if(pan){pan.pan.value=state.audio[name].pan/100;src.connect(gain);gain.connect(pan);pan.connect(dest)}else{src.connect(gain);gain.connect(dest)}state.audioNodes[name]={gain,pan}}}await state.audioContext.resume();for(const t of dest.stream.getAudioTracks())output.addTrack(t)}const draw=()=>{ctx.fillStyle=state.bgColor;ctx.fillRect(0,0,canvas.width,canvas.height);if(!state.imageOnTop)drawImageLayer(ctx,canvas);if(state.visible&&video.videoWidth&&video.videoHeight&&state.video.width>0&&state.video.height>0){const boxW=canvas.width*state.video.width/100,boxH=canvas.height*state.video.height/100,x=(canvas.width-boxW)/2+state.video.x*canvas.width/100,y=(canvas.height-boxH)/2+state.video.y*canvas.height/100;ctx.save();ctx.beginPath();ctx.rect(0,0,canvas.width,canvas.height);ctx.clip();ctx.filter=colorFilterCss();ctx.globalAlpha=state.values.Opacity;if(state.aspect){const fit=Math.min(boxW/video.videoWidth,boxH/video.videoHeight),w=video.videoWidth*fit,h=video.videoHeight*fit;ctx.drawImage(video,x+(boxW-w)/2,y+(boxH-h)/2,w,h)}else ctx.drawImage(video,x,y,boxW,boxH);ctx.filter="none";ctx.globalAlpha=1;ctx.restore()}if(state.imageOnTop)drawImageLayer(ctx,canvas);let y=canvas.height*.13;ctx.font=`600 ${Math.round(canvas.width*.025)}px DM Sans, sans-serif`;ctx.fillStyle='#fff';for(const widget of state.widgets){const p=state.positions.overlay;ctx.fillText(widget==='webcam'?'Webcam':widget==='text'?'Your text':'Overlay',canvas.width*.08+p.x*canvas.width/480,y+p.y*canvas.height/480);y+=canvas.height*.05}};state.sceneTimer=setInterval(draw,1000/Math.max(20,state.fps));draw();return output}
function setOrientation(value){state.orientation=value;if(state.modal==='editor')renderModal();else dashboard()}
function login(){app.innerHTML=`<div class="auth-page"><div class="auth-brand">Luma<span>Cast</span></div><div class="auth-orbit"><div class="orbit-ring"></div><div class="orbit-dot"></div><div class="orbit-shadow"></div></div><div class="auth-actions"><button class="provider twitch" onclick="signIn('Twitch')"><b>▣</b>Sign in with Twitch</button><button class="provider youtube" onclick="signIn('YouTube')"><b>▶</b>Sign in with YouTube</button><button class="provider facebook" onclick="signIn('Facebook')"><b>f</b>Sign in with Facebook</button><button class="provider trovo" onclick="signIn('Trovo')"><b>✦</b>Sign in with Trovo</button><button class="auth-link" onclick="openModal('ingestForm')">Enter with RTMP</button><button class="auth-link support" onclick="toast('Support: help@lumacast.live')">Support</button></div><p class="auth-foot">Your stream. Your stage. <span>© 2026 LumaCast</span></p></div>`;}
function signIn(provider){if(provider==='YouTube'){openModal('youtubeSetup');return}state.logged=true;dashboard();toast(`${provider} OAuth is not configured. Opened the LumaCast demo studio.`)}
function dashboard(){state.page='dashboard';app.innerHTML=`<div class="main"><header class="topbar"><div class="brand">${logo}<span>LumaCast</span></div><div class="top-actions"><button class="icon-button" onclick="openModal('settings')">⚙ &nbsp;Settings</button><div class="avatar">A</div><button class="pill" onclick="logout()">Log out</button></div></header><main class="workspace"><div class="welcome"><div><h1>Good evening, Alex</h1><p>Your studio is ready when you are.</p></div><span class="status">● &nbsp;Studio ready</span></div><div class="grid"><section><div class="card"><div class="card-head"><h2>Live studio</h2><span class="section-label">${state.orientation} · ${state.resolution} · ${state.fps} fps</span></div><div class="orientation-bar"><span>Orientation</span><select ${state.live?'disabled':''} onchange="setOrientation(this.value)">${["Auto","Portrait","Landscape"].map(o=>`<option ${state.orientation===o?"selected":""}>${o}</option>`).join("")}</select><small>${state.orientation==='Portrait'?'9:16':'16:9'}</small></div><div class="stage" style="width:${state.orientation==='Portrait'?'min(100%, 31vh)':'100%'};margin:0 auto;aspect-ratio:${sceneRatio()}">${state.live?'<span class="live-badge">CAPTURING</span>':''}<span class="stage-label">${state.live?'00:12:48':'PREVIEW'}</span><video id="screenPreview" class="feed-video ${state.outputCapture?'':'hidden'}" autoplay muted playsinline></video>${imageLayer()}<div class="stage-placeholder ${state.outputCapture?'hidden':''}"><span class="cam-icon">◉</span><strong>Your stream preview</strong><span>Start screen capture to preview your game</span></div></div><div class="stage-footer"><div class="stream-info">● &nbsp;<strong>${state.live?'Screen capture active':'Capture not running'}</strong> &nbsp;·&nbsp; ${state.live?'sending through RTMPS relay':'Choose a source to begin'}</div><div class="stream-buttons"><button class="secondary" onclick="openModal('editor')">Edit scene</button><button class="secondary" onclick="openModal('audio')">Audio</button><button class="start ${state.live?'live':''}" onclick="toggleLive()">${state.live?'■  Stop capture':'▶  Start capture'}</button></div></div><div class="metric-row"><div class="metric"><small>VIDEO QUALITY</small><strong>${state.resolution}</strong></div><div class="metric"><small>FRAME RATE</small><strong>${state.fps} fps</strong></div><div class="metric"><small>BITRATE</small><strong>${state.bitrate.toLocaleString()} <small style="display:inline">kbps</small></strong></div></div></div><div class="bottom-nav"><button class="nav-tab active">Overview</button><button class="nav-tab" onclick="openModal('editor')">Scene &amp; overlays</button><button class="nav-tab" onclick="openModal('settings')">Stream settings</button></div></section><aside class="side-stack"><section class="card"><div class="card-head"><h2>Stream setup</h2><button class="link-button" onclick="openModal('settings')">Configure →</button></div><div class="quick-row"><span>Destination</span><span>${state.youtubeChannel||state.activeIngest}</span></div><div class="quick-row"><span>Resolution</span><span>${state.resolution} <a class="link-button" onclick="openModal('resolution')">Change</a></span></div><div class="quick-row"><span>Encoder</span><span>H.264 Main</span></div><div class="quick-row"><span>Audio bitrate</span><span>128 kbps</span></div></section><section class="card"><div class="card-head"><h2>Recent activity</h2><span class="section-label">Today</span></div><div class="event"><i class="event-dot"></i><p>Studio is ready to go.<br><small>Just now</small></p></div><div class="event"><i class="event-dot" style="background:#d4c7ea"></i><p>Stream profile synced successfully.<br><small>9:42 AM</small></p></div></section><section class="card"><div class="card-head"><h2>Quick tip</h2><span>✦</span></div><p class="section-label" style="line-height:1.6;margin:0">For the smoothest stream, keep your bitrate matched to your network. Start at 7,000 kbps for 720p60.</p></section></aside></div></main></div>`;syncHomeScenePreview();if(state.outputCapture){const v=document.querySelector('#screenPreview');if(v){v.srcObject=state.outputCapture;v.play().catch(()=>{})}}}
function syncHomeScenePreview(){const stage=document.querySelector('.stage');if(!stage)return;stage.style.background=state.bgColor;stage.innerHTML=`${videoLayer()}${imageLayer()}${state.widgets.map(w=>`<span class="widget" style="transform:translate(${state.positions.overlay.x}px,${state.positions.overlay.y}px)">${w==='webcam'?'Webcam':w==='text'?'Your text':'Overlay'}</span>`).join('')}<span class="stage-label">${state.live?'LIVE PREVIEW':'SCENE PREVIEW'}</span>${state.live?'<span class="live-badge">LIVE</span>':''}`;const v=stage.querySelector('#editorVideoPreview');if(v&&state.capture){v.srcObject=state.capture;v.muted=true;v.play().catch(()=>{})}}
function logout(){state.logged=false;state.live=false;login()}
function connectRelaySocket(url,initial,mimeType){const ws=new WebSocket(url);ws.binaryType='arraybuffer';state.ws=ws;ws.onopen=()=>{state.reconnects=0;if(initial&&!state.live){if(!state.capture)return;state.live=true;state.recorder=new MediaRecorder(state.outputCapture,{mimeType});state.recorder.ondataavailable=e=>{if(e.data.size&&state.ws?.readyState===WebSocket.OPEN)state.ws.send(e.data)};state.recorder.start(500);dashboard();toast(`Streaming ${state.orientation==='Portrait'?'Portrait 9:16':'Landscape 16:9'} to your ingest. Stop manually when finished.`)}else toast('Relay reconnected; stream capture continues.')};ws.onerror=()=>{if(initial&&!state.live)toast('Could not connect to the streaming relay.')};ws.onclose=()=>{if(state.live&&state.capture){state.ws=null;if(state.reconnects<25){state.reconnects++;setTimeout(()=>{if(state.live)connectRelaySocket(url,false,mimeType)},1000)}else toast('Relay is unavailable. Capture remains active; use Stop capture when ready.')}else if(state.capture){state.capture.getTracks().forEach(t=>t.stop());state.capture=null;state.outputCapture?.getTracks().forEach(t=>t.stop());state.outputCapture=null;clearInterval(state.sceneTimer);state.audioContext?.close();state.audioNodes={}}}}
async function toggleLive(){if(state.live){const recorder=state.recorder;if(recorder?.state!=='inactive')await new Promise(resolve=>{recorder.addEventListener('stop',resolve,{once:true});recorder.stop()});state.live=false;state.capture?.getTracks().forEach(t=>t.stop());state.outputCapture?.getTracks().forEach(t=>t.stop());state.micStream?.getTracks().forEach(t=>t.stop());clearInterval(state.sceneTimer);state.audioContext?.close();state.audioNodes={};const ws=state.ws;if(ws?.readyState===WebSocket.OPEN){while(ws.bufferedAmount>0)await new Promise(r=>setTimeout(r,80));ws.close()}state.ws=null;if(state.relaySession)await fetch('/api/stream/stop',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({session:state.relaySession})}).catch(()=>{});state.relaySession='';state.capture=null;state.outputCapture=null;state.recorder=null;toast('Stream stopped.');dashboard();return}try{if(state.activeIngest==='YouTube'&&!state.youtubeToken)throw Error('Connect your YouTube account first. Use Sign in with YouTube, then start the stream.');if(!navigator.mediaDevices?.getDisplayMedia)throw Error('This browser does not support screen capture. Try a current desktop Chrome or Edge browser over HTTPS.');const types=['video/webm;codecs=vp8,opus','video/webm;codecs=vp8','video/webm'];const mimeType=types.find(t=>MediaRecorder.isTypeSupported(t));if(!mimeType)throw Error('This browser cannot provide WebM media to the relay. Use a current desktop Chrome or Edge browser.');state.capture=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:30},audio:true});state.capture.getVideoTracks()[0]?.addEventListener('ended',()=>{if(state.live)toggleLive()},{once:true});state.outputCapture=await makeSceneCapture(state.capture);const selectedIngest=state.ingests.find(x=>x.title===state.activeIngest);const ingest=selectedIngest||((state.activeIngest==='YouTube'&&state.youtubeToken)?await createYouTubeIngest():null);const response=await fetch('/api/stream/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({orientation:state.orientation==='Portrait'?'Portrait':'Landscape',fps:state.fps,bitrate:state.bitrate,server:ingest?.server,key:ingest?.key})});const result=await response.json();if(!response.ok)throw Error(result.error||'Relay could not start.');state.relaySession=result.session;const wsUrl=new URL(result.websocket,location.href);wsUrl.protocol=location.protocol==='https:'?'wss:':'ws:';state.wsUrl=wsUrl.toString();state.reconnects=0;connectRelaySocket(state.wsUrl,true,mimeType)}catch(e){state.capture?.getTracks().forEach(t=>t.stop());state.outputCapture?.getTracks().forEach(t=>t.stop());clearInterval(state.sceneTimer);state.audioContext?.close();state.capture=null;state.outputCapture=null;toast(e.message||'Screen capture or relay failed.')}}
async function youtubeApi(resource,params,method='GET',body){const url=new URL(`https://www.googleapis.com/youtube/v3/${resource}`);for(const [k,v] of Object.entries(params||{}))if(v!==undefined&&v!==null)url.searchParams.set(k,v);const response=await fetch(url,{method,headers:{Authorization:`Bearer ${state.youtubeToken}`,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error?.message||`YouTube API error (${response.status})`);return data}
async function createYouTubeIngest(){if(!state.youtubeToken)throw Error('Connect your YouTube account first, then start the stream.');const title=`${state.youtubeChannel||'LumaCast'} live`;const broadcast=await youtubeApi('liveBroadcasts',{part:'snippet,status,contentDetails'},'POST',{snippet:{title,scheduledStartTime:new Date(Date.now()+5*60*1000).toISOString()},status:{privacyStatus:'unlisted',selfDeclaredMadeForKids:false},contentDetails:{enableAutoStart:true,enableAutoStop:false,enableDvr:true,monitorStream:{enableMonitorStream:false}}});const stream=await youtubeApi('liveStreams',{part:'snippet,cdn'},'POST',{snippet:{title:`${title} ingest`},cdn:{frameRate:state.fps>=60?'60fps':'30fps',ingestionType:'rtmp',resolution:'variable'}});await youtubeApi('liveBroadcasts/bind',{part:'id,contentDetails,status',id:broadcast.id,streamId:stream.id},'POST');const info=stream.cdn?.ingestionInfo;if(!info?.ingestionAddress||!info?.streamName)throw Error('YouTube did not return an RTMP ingest address and stream key.');return {server:info.ingestionAddress,key:info.streamName,broadcastId:broadcast.id}}
async function toggleLive(){if(state.live){const recorder=state.recorder;if(recorder?.state!=='inactive')await new Promise(resolve=>{recorder.addEventListener('stop',resolve,{once:true});recorder.stop()});state.live=false;state.capture?.getTracks().forEach(t=>t.stop());state.outputCapture?.getTracks().forEach(t=>t.stop());state.micStream?.getTracks().forEach(t=>t.stop());clearInterval(state.sceneTimer);state.audioContext?.close();state.audioNodes={};const ws=state.ws;if(ws?.readyState===WebSocket.OPEN){while(ws.bufferedAmount>0)await new Promise(r=>setTimeout(r,80));ws.close()}state.ws=null;if(state.relaySession)await fetch('/api/stream/stop',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({session:state.relaySession})}).catch(()=>{});state.relaySession='';state.capture=null;state.outputCapture=null;state.recorder=null;toast('YouTube stream stopped.');dashboard();return}try{if(!state.capture){if(!navigator.mediaDevices?.getDisplayMedia)throw Error('Screen capture is unavailable here. Open this site in desktop Chrome or Edge, then allow screen sharing.');state.capture=await navigator.mediaDevices.getDisplayMedia({video:{frameRate:30},audio:true});state.capture.getVideoTracks()[0]?.addEventListener('ended',()=>{if(state.live)toggleLive();else{state.capture=null;state.outputCapture?.getTracks().forEach(t=>t.stop());state.outputCapture=null;clearInterval(state.sceneTimer);dashboard();toast('Screen capture ended.')}},{once:true});state.outputCapture=await makeSceneCapture(state.capture);dashboard();toast('Screen captured and shown in the scene preview. Click Start YouTube Live when ready.');return}const types=['video/webm;codecs=vp8,opus','video/webm;codecs=vp8','video/webm'];const mimeType=types.find(t=>MediaRecorder.isTypeSupported(t));if(!mimeType)throw Error('This browser cannot provide WebM media to the relay. Use current desktop Chrome or Edge.');const selectedIngest=state.ingests.find(x=>x.title===state.activeIngest);const ingest=selectedIngest||((state.activeIngest==='YouTube'&&state.youtubeToken)?await createYouTubeIngest():null);const response=await fetch('/api/stream/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({orientation:state.orientation==='Portrait'?'Portrait':'Landscape',fps:state.fps,bitrate:state.bitrate,server:ingest?.server,key:ingest?.key})});const result=await response.json();if(!response.ok)throw Error(result.error||'Relay could not start.');state.relaySession=result.session;const wsUrl=new URL(result.websocket,location.href);wsUrl.protocol=location.protocol==='https:'?'wss:':'ws:';state.wsUrl=wsUrl.toString();state.reconnects=0;connectRelaySocket(state.wsUrl,true,mimeType)}catch(e){toast(e.message||'Screen capture or YouTube stream failed.')}}
function openModal(name){state.modal=name;renderModal();if(name==='audio')refreshMicDevices().then(()=>{if(state.modal==='audio')renderModal()})}
function closeModal(){state.modal='';if(state.logged)dashboard()}
function modalHead(title,sub=''){return `<div class="modal-top"><button class="close" onclick="closeModal()">‹</button><div style="text-align:center"><h2>${title}</h2>${sub?`<small class="section-label">${sub}</small>`:''}</div><button class="pill" onclick="closeModal()">Done</button></div>`}
function renderModal(){if(!state.modal)return;document.querySelector('#modalBg')?.remove();let body='';const m=state.modal;
if(m==='settings')body=`${modalHead('Settings')}<div class="settings-group"><h3>Account</h3><div class="settings-card"><div class="setting-row clickable"><span>Stream notifications</span><span class="value">›</span></div><div class="setting-row clickable"><span>Ingests</span><button class="link-button" onclick="openModal('ingests')">${state.activeIngest}　›</button></div><div class="setting-row"><button class="link-button" onclick="toast('Account help is coming soon.')">How to delete account?</button></div><div class="setting-row"><button class="link-button red" onclick="logout()">Logout</button></div></div></div><div class="settings-group"><h3>Video</h3><div class="settings-card"><div class="setting-row clickable" onclick="openModal('resolution')"><span>Resolution</span><span class="value">${state.resolution}　›</span></div><div class="setting-row"><span>Bitrate</span><strong class="value" id="bitrateLabel">${state.bitrate} kbps</strong></div><input class="range bitrate-range" aria-label="Video bitrate" type="range" min="1500" max="15000" step="500" value="${state.bitrate}" oninput="state.bitrate=+this.value;document.querySelector('#bitrateLabel').textContent=this.value+' kbps'"><div class="setting-row clickable" onclick="openModal('fps')"><span>Frames per second</span><span class="value">${state.fps}　›</span></div><div class="setting-row clickable" onclick="openModal('color')"><span>Color Correction</span><span class="value">Manual　›</span></div><div class="setting-row clickable" onclick="openModal('advanced')"><span>Advanced settings</span><span class="value">h264 Main　›</span></div></div><p class="helper">For settings to work, you have to restart the stream.</p></div><div class="settings-group"><h3>Audio</h3><div class="settings-card"><div class="highlight setting-row"><span>Bitrate</span><span>128 kbps</span></div></div></div>`;
if(m==='resolution')body=`${modalHead('Resolution','Choose a stream quality')}<div class="settings-card">${resolutions.map(([a,b])=>`<div class="choice" onclick="state.resolution='${a}';renderModal()"><div><strong>${a}</strong><p>${b}</p></div>${state.resolution===a?'<span class="check">✓</span>':''}</div>`).join('')}</div>`;
if(m==='fps')body=`${modalHead('Frames per second')}<div class="settings-card">${[20,30,60].map(a=>`<div class="choice" onclick="state.fps=${a};renderModal()"><strong style="color:var(--purple)">${a} fps</strong>${state.fps===a?'<span class="check">✓</span>':''}</div>`).join('')}</div>`;
if(m==='advanced')body=`${modalHead('Advanced settings')}<div class="settings-card"><div class="setting-row clickable"><span>AVC</span><span class="value">h264 Main　›</span></div>${Object.entries(state.settings).map(([n,v])=>`<div class="setting-row"><div><div>${n}</div>${n==='Adaptive Bitrate'?'<p class="helper" style="margin:4px 0">Automatically adjusts your bitrate based on your network. Reduces lags in network games.</p>':''}</div><input class="switch" type="checkbox" ${v?'checked':''} onchange="state.settings['${n}']=this.checked"></div>`).join('')}<div class="setting-row" style="display:block;padding:14px 0"><small class="section-label">Network Priority</small><div class="segmented" style="margin-top:9px">${['High','Normal','Low'].map(n=>`<button class="${state.priority===n?'selected':''}" onclick="state.priority='${n}';renderModal()">${n==='Image'?'Image 1':n}</button>`).join('')}</div></div></div><div class="settings-group"><h3>Cooling - Performance boost</h3><div class="settings-card"><div class="slider-line"><span>♨ Performance</span><input class="range" type="range" min="0" max="5" value="2"><span class="slider-value">2</span></div></div><p class="helper">Note: boost the stream performance with the cost of overheating the device.</p></div><div class="settings-group"><h3>HTML Overlay</h3><div class="settings-card"><div class="setting-row"><span>Allow HTML overlays</span><input class="switch" type="checkbox"></div></div></div>`;
if(m==='color')body=`${modalHead('Color Correction','Manual adjustments')}<div class="editor-preview" style="aspect-ratio:16/7;background:linear-gradient(120deg,#bc8c78,#4b7790 48%,#29243b)"><span>Live preview · Camera not connected</span></div><div class="settings-card">${[['Gamma','Controls mid-tones.',-1,3,0],['Contrast','Adjusts the difference between light and dark areas.',-2,2,0],['Brightness','Increases or decreases overall picture brightness.',-1,1,0],['Saturation','Controls color intensity and vibrancy.',-1,5,0],['Hue Shift','Shifts all colors along the color spectrum wheel.',-180,180,0],['Opacity','Sets transparency levels for the source.',0,1,1]].map(([n,d,min,max,def])=>`<div class="slider-line"><div><b>${n}</b><small>${d}</small></div><input class="range" type="range" min="${min}" max="${max}" step="0.1" value="${state.values[n]}" oninput="state.values['${n}']=+this.value;this.nextElementSibling.textContent=Number(this.value).toFixed(1)"><span class="slider-value">${Number(state.values[n]).toFixed(1)}</span><button class="link-button" title="Reset" onclick="state.values['${n}']=${def};renderModal()">↺</button></div>`).join('')}</div><button class="link-button" style="margin:16px 0" onclick="state.values={Gamma:0,Contrast:0,Brightness:0,Saturation:0,'Hue Shift':0,Opacity:1};renderModal()">Reset all to default</button>`;
if(m==='ingests')body=`${modalHead('Ingests','Choose where your stream is sent')}<div class="settings-card"><div class="choice ingest-choice" onclick="setActiveIngest('YouTube');renderModal()"><div><strong style="color:var(--purple)">▶ &nbsp;YouTube Live</strong><p>Stream to your YouTube channel using its RTMPS ingest endpoint.</p></div><span class="ingest-action">${state.activeIngest==='YouTube'?'✓ Selected':'Select'}</span></div>${state.ingests.map((x,i)=>`<div class="choice ingest-choice" onclick="setActiveIngest('${x.title.replaceAll("'","\\'")}');renderModal()"><div><strong style="color:var(--purple)">${x.title}</strong><p>${x.server}</p></div><div class="ingest-actions"><span class="ingest-action">${state.activeIngest===x.title?'✓ Selected':'Select'}</span><button class="link-button red" onclick="event.stopPropagation();removeIngest(${i})">Remove</button></div></div>`).join('')}</div><button class="primary" style="width:100%;margin-top:16px" onclick="openModal('ingestForm')">＋ Add custom ingest</button><p class="helper">A secure streaming relay is required to forward browser screen capture to YouTube RTMPS.</p>`;
if(m==='ingestForm')body=`${modalHead('Add custom ingest')}<form class="settings-card" id="ingestForm"><label class="label">Title</label><input class="field" name="title" placeholder="My streaming server" required><label class="label">Server URL</label><input class="field" name="server" placeholder="rtmps://a.rtmps.youtube.com/live2" required><label class="label">Server key</label><input class="field" name="key" type="password" placeholder="Stream key" required><p class="helper">The stream key is used for this browser session only and is not saved. Use a protected backend for real streaming.</p><button class="primary" style="width:100%;margin:12px 0">Save ingest</button></form>`;
if(m==='youtubeSetup')body=`${modalHead('Connect YouTube Live')}<div class="settings-card" style="padding:20px"><div style="font-size:38px;color:#f33">▶</div><h3>Connect your channel</h3><p class="section-label" style="line-height:1.6">Sign in with Google OAuth to connect your YouTube channel. A secure RTMPS relay is still needed to forward captured video to YouTube.</p><label class="label">Google OAuth client ID</label><input class="field" id="googleClientId" placeholder="123456789-abc.apps.googleusercontent.com" autocomplete="off"><p class="helper">Use the OAuth client ID from Google Cloud Credentials, not your YouTube handle or email. It ends in <b>.apps.googleusercontent.com</b>. Add <b>http://localhost:4173</b> as an authorized JavaScript origin.</p><button class="primary" style="width:100%;margin-top:15px" onclick="connectYouTube()">Continue with Google</button><p class="helper">Enable YouTube Data API v3 and add your Google account as a test user if the consent screen is in Testing. Never use a client secret in this page.</p><p class="helper"><b>Authorization blocked?</b> Google blocks OAuth sign-in inside some embedded browsers. Open this same site in Chrome or Edge and try again.</p></div>`;
if(m==='audio'){body=`${modalHead('Audio mixer','Live mix controls')}<div class="settings-card"><div class="setting-row"><span>Speaker · device audio</span><input class="switch" type="checkbox" ${state.speakerEnabled?'checked':''} onchange="state.speakerEnabled=this.checked;updateAudioNodes()"></div><p class="helper">System audio is captured when you select “Share tab audio” or “Share system audio” in the browser screen picker.</p></div>${audioChannel('game','Speaker')}${audioChannel('mic','Microphone')}<div class="settings-card"><div class="setting-row"><span>Microphone source</span><select id="micSource" onchange="state.micManualSelection=true;state.micDeviceId=this.value;state.micDeviceLabel=this.options[this.selectedIndex].text">${state.micDevices.map(d=>`<option value="${d.deviceId}" ${d.deviceId===state.micDeviceId?'selected':''}>${d.label||'Microphone'}</option>`).join('')||'<option value="">Device Microphone (detected after permission)</option>'}</select></div><small class="helper">Selected: ${state.micDeviceLabel}${state.selectedHeadset?' · '+state.selectedHeadset:''}</small></div><button class="secondary" style="width:100%" onclick="enableMic()">${state.micStream?'Refresh microphone ✓':'Enable microphone'}</button><p class="helper">Headset microphones are preferred when the browser reports one; otherwise the device microphone is selected. Available names appear after microphone permission is granted.</p>`}
if(m==='editor')body=editorMarkup();
if(m==='mode')body=`${modalHead('Mode')}<div class="settings-card">${[['Advanced','For more powerful devices. All functionality is enabled.'],['Advanced (Fullscreen)','For more powerful devices. Overlay is fullscreen.'],['Turbo','For older devices. Widgets and background disabled. Speed is a priority.']].map(([n,d])=>`<div class="choice" onclick="state.mode='${n}';openModal('editor')"><div><strong style="color:var(--purple)">▣ &nbsp;${n}</strong><p>${d}</p></div>${state.mode===n?'<span class="check">✓</span>':''}</div>`).join('')}</div>`;
if(m==='add')body=`${modalHead('Add Widget')}<div class="settings-card">${[['Add webcam (320×240)','webcam'],['Add Text','text'],['Add Image from Photos','photos'],['Add Image from Files','files'],['Add HTML overlay','html']].map(([n,x])=>`<div class="setting-row"><button class="link-button" onclick="addWidget('${x}')">${n==='Image'?'Image 1':n}</button></div>`).join('')}</div><div class="settings-group"><h3>Discover</h3><div class="settings-card"><div class="setting-row"><span class="link-button">Brawl Stars · Guide for LumaCast</span></div></div><p class="helper">Your personal trophy and W/L stats updated in real-time.</p></div>`;
app.insertAdjacentHTML('beforeend',`<div class="modal-bg" id="modalBg" onclick="if(event.target===this)closeModal()"><section class="modal">${body}</section></div>`);document.querySelector('#ingestForm')?.addEventListener('submit',saveIngest);const preview=document.querySelector('#editorVideoPreview');if(preview&&state.capture)preview.srcObject=state.capture}
function setActiveIngest(title){state.activeIngest=title;sessionStorage.setItem('lumacast-active-ingest',title)}
function saveIngest(e){e.preventDefault();const f=new FormData(e.currentTarget),entry={title:f.get('title').trim(),server:f.get('server').trim(),key:f.get('key')};state.ingests.push(entry);setActiveIngest(entry.title);sessionStorage.setItem('lumacast-ingest-keys',JSON.stringify(Object.fromEntries(state.ingests.map(x=>[x.title,x.key]))));localStorage.setItem('lumacast-ingests',JSON.stringify(state.ingests.map(({title,server})=>({title,server}))));state.logged=true;dashboard();toast('RTMP ingest saved for this session. Select it in Settings to stream without Google sign-in; the stream key is not saved after this session.')}
function removeIngest(i){state.ingests.splice(i,1);localStorage.setItem('lumacast-ingests',JSON.stringify(state.ingests));if(!state.ingests.some(x=>x.title===state.activeIngest))state.activeIngest='YouTube';renderModal()}
function connectYouTube(){const id=document.querySelector('#googleClientId')?.value.trim();if(!id){toast('Enter the OAuth client ID from Google Cloud Credentials.');return}if(!id.endsWith('.apps.googleusercontent.com')||/[@\s]/.test(id)){toast('That looks like a channel handle or email. Paste the OAuth client ID ending in .apps.googleusercontent.com.');return}if(!window.google?.accounts?.oauth2){if(!document.querySelector('#gisScript')){const s=document.createElement('script');s.id='gisScript';s.src='https://accounts.google.com/gsi/client';s.onload=()=>toast('Google sign-in is ready. Click Continue with Google again.');s.onerror=()=>toast('Could not load Google sign-in. Check your connection.');document.head.append(s)}else toast('Google sign-in is loading. Try again in a moment.');return}const client=google.accounts.oauth2.initTokenClient({client_id:id,scope:'https://www.googleapis.com/auth/youtube.force-ssl',callback:async r=>{if(r.error){toast(`YouTube authorization failed: ${r.error}. Check your OAuth consent screen and test-user setup.`);return}state.youtubeToken=r.access_token;try{const q=await fetch('https://www.googleapis.com/youtube/v3/channels?part=snippet&mine=true',{headers:{Authorization:`Bearer ${r.access_token}`}});const data=await q.json();if(!q.ok||!data.items?.length)throw Error(data.error?.message||'No eligible YouTube channel was found');state.youtubeChannel=data.items[0].snippet.title;state.logged=true;state.activeIngest='YouTube';dashboard();toast(`Connected to ${state.youtubeChannel}. Start YouTube live from the studio when ready.`)}catch(e){toast(`YouTube connection failed: ${e.message}`)}}});client.requestAccessToken()}
function editorMarkup(){return `<div class="scene-editor-head"><button class="scene-close" onclick="closeModal()">×</button><h2>${state.tab==='Image'?'Image 1':state.tab}</h2><button class="pill-mode" onclick="openModal('mode')">Mode: ${state.mode}　▣</button></div><div class="orientation-bar"><span>Canvas orientation</span><select ${state.live?'disabled':''} onchange="setOrientation(this.value)">${["Auto","Portrait","Landscape"].map(o=>`<option ${state.orientation===o?"selected":""}>${o}</option>`).join("")}</select><small>${state.orientation==='Portrait'?'9:16':'16:9'}</small></div><div class="editor-preview" style="width:${state.orientation==='Portrait'?'min(100%, 31vh)':'100%'};margin:0 auto;background:${state.bgColor};aspect-ratio:${sceneRatio()}">${videoLayer()}${imageLayer()}${state.widgets.map(w=>`<span class="widget" style="transform:translate(${state.positions.overlay.x}px,${state.positions.overlay.y}px)">${w==='webcam'?'Webcam':w==='text'?'Your text':w==='photos'||w==='files'?'Image':'Overlay'}</span>`).join('')}</div><div class="tabs">${['Add','Watermark','Video',...(state.image?['Image']:[]),'Background'].map(n=>`<button class="${state.tab===n?'active':''}" onclick="state.tab='${n}';renderModal()">${n==='Image'?'Image 1':n}</button>`).join('')}</div>${state.tab==='Add'?`<div class="settings-card">${['Add webcam (320×240)','Add Text','Add Image from Photos','Add Image from Files','Add HTML overlay'].map((n,i)=>`<div class="setting-row"><button class="link-button" onclick="addWidget('${['webcam','text','photos','files','html'][i]}')">${n==='Image'?'Image 1':n}</button></div>`).join('')}</div>${state.image?imageControls():''}` :state.tab==='Image'&&state.image?`${imageControls()}`:state.tab==='Video'?`<div class="settings-card"><div class="setting-row"><span>Visible</span><input class="switch" type="checkbox" ${state.visible?'checked':''} onchange="state.visible=this.checked;renderModal()"></div><div class="setting-row"><span>Original Aspect Ratio</span><input class="switch" type="checkbox" ${state.aspect?'checked':''} onchange="state.aspect=this.checked;renderModal()"></div><div style="padding:10px 0">Position inside scene</div>${positionSliders('video','Video')}${nudgePad('video')}<div style="text-align:center;padding:14px"><button class="link-button" onclick="state.video={width:100,height:100,x:0,y:0};state.visible=true;state.aspect=false;renderModal()">Reset position</button></div></div>`:state.tab==='Background'?`<div class="row-card"><span>Color</span><label class="color-preview"><input type="color" value="${state.bgColor}" style="opacity:0;width:20px" oninput="state.bgColor=this.value;renderModal()"></label></div><div class="row-card"><span>Image</span><button class="link-button" onclick="document.querySelector('#photoInput').click()">Update</button></div><div class="row-card"><span>Background</span><button class="link-button" onclick="toast('Pattern options opened')">Pattern</button></div><div class="slider-line"><span>Pattern size</span><input class="range" type="range"><span></span></div><button class="remove" onclick="state.image=null;renderModal()">Remove Image</button>`:`<div class="settings-card"><div class="setting-row"><span>Watermark</span><span class="value">Visible</span></div></div>`}`}
function addWidget(k){if(k==='photos'){document.querySelector('#photoInput').click();return}if(k==='files'){document.querySelector('#fileInput').click();return}if(k==='webcam'){camera();return}if(k==='text'){let t=prompt('Text for your overlay','Your text');if(t)state.widgets.push('text')}else if(k==='html'){let url=prompt('HTML overlay URL (https://)');if(url)toast('Overlay URL added to your scene')}openModal('editor')}
async function camera(){if(!navigator.mediaDevices?.getUserMedia){toast('Camera access needs HTTPS or localhost.');return}try{let stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});state.widgets.push('webcam');openModal('editor');toast('Camera connected. Browser permission granted.')}catch(e){toast('Allow camera access in your browser to use the webcam.')}}
for(const id of ['photoInput','fileInput'])document.querySelector('#'+id).addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){toast('This preview supports image files.');return}state.image=URL.createObjectURL(f);state.widgets.push(id==='photoInput'?'photos':'files');state.tab='Image';openModal('editor')});
document.addEventListener('input',e=>{if(state.modal==='color'&&e.target.matches('.slider-line input[type="range"]'))applyCorrectionPreview()});
new MutationObserver(()=>{applyCorrectionPreview();const b=document.querySelector('.start');if(!b)return;const label=state.live?'■  Stop YouTube Live':state.capture?'▶  Start YouTube Live':'▣  Capture screen';if(b.textContent!==label)b.textContent=label}).observe(app,{childList:true,subtree:true});
login();
